.demo-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); gap: 20px; padding: 40px; }
.service-card {
  background: var(--bg-alt); border: 1px solid var(--border); border-radius: 16px; padding: 32px;
  min-height: 220px; transition: border-color 0.3s;
}
.service-card .title { font-weight: 700; font-size: 22px; letter-spacing: -0.02em; margin-bottom: 10px; }
.service-card .desc { font-size: 14px; color: var(--text-muted); line-height: 1.55; }

/* Duas camadas: um anel só na borda (o gradiente é recortado com máscara,
   sobrando apenas a moldura de 1px) e um brilho fraco derramando para dentro.

   Dois gatilhos, porque são dois mundos:
   - .fx-on (mouse): acende no hover, seguindo o cursor.
   - .fx-touch (dedo): acende sozinho quando o card entra na tela e apaga em
     seguida. Sem cursor não há posição de repouso — um hover simulado ficaria
     preso onde a pessoa tocou por último, que é pior que não ter. */
.service-card {
  position: relative;
  isolation: isolate;
}

:is(.fx-on, .fx-touch) .service-card::before,
:is(.fx-on, .fx-touch) .service-card::after {
  content: '';
  position: absolute; inset: 0;
  border-radius: inherit;
  pointer-events: none;
  opacity: 0;
  transition: opacity 0.35s ease;
}

/* o anel: gradiente menos o miolo, sobra a borda */
:is(.fx-on, .fx-touch) .service-card::before {
  padding: 1px;
  background: radial-gradient(
    260px circle at var(--card-x, 50%) var(--card-y, 50%),
    var(--accent-hover) 0%,
    rgba(14, 165, 233, 0.35) 35%,
    transparent 70%
  );
  -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
  mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
  mask-composite: exclude;
  z-index: 2;
}

/* o derrame para dentro, bem fraco */
:is(.fx-on, .fx-touch) .service-card::after {
  background: radial-gradient(
    240px circle at var(--card-x, 50%) var(--card-y, 50%),
    rgba(14, 165, 233, 0.09) 0%,
    transparent 65%
  );
  z-index: 0;
}

.fx-on .service-card:hover::before,
.fx-on .service-card:hover::after {
  opacity: 1;
}

/* No toque o gradiente não tem para onde apontar, então nasce do topo do card
   e o brilho passa uma vez, quando ele entra na tela. */
.fx-touch .service-card::before,
.fx-touch .service-card::after {
  --card-x: 50%;
  --card-y: 0%;
}
.fx-touch .service-card.is-lit::before,
.fx-touch .service-card.is-lit::after {
  animation: fx-card-pulse 1.5s ease-out forwards;
}
@keyframes fx-card-pulse {
  0%   { opacity: 0; }
  35%  { opacity: 1; }
  100% { opacity: 0; }
}

/* O anel substitui o realce de borda que esses cards já faziam no hover;
   os dois juntos deixariam a moldura dobrada. */
.fx-on .service-card:hover { border-color: var(--border); }

